            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x43B2B342187333F5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x6AD480FA6D6643C5ULL), 13U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0x4968826AD5D62144ULL) + aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 26U)) & S_SALT1];
