            aOrbiterB = ((aOrbiterB ^ aOrbiterJ) ^ 0xDBDB1B3A91D45B8BULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 67U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x829A7B9F8C446189ULL), 37U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0xCF70DFAA551D21D5ULL) + aKeyRotateAOrbiterUpdateSaltF[(((255U - aIndex) + 241U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x248E362DF6A8B03BULL;
