            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x4C187265E771716EULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 122U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0xFE40977EF66A1406ULL;
