            //
            aIngress = (RotL64(aWindLaneD[((aIndex + 4845U)) & S_BLOCK1], 21U) ^ RotL64(aWindLaneB[((aIndex + 7712U)) & S_BLOCK1], 37U));
            aIngress ^= (RotL64(aShadowLaneA[((aIndex + 1382U)) & S_BLOCK1], 52U) ^ RotL64(aKeyRowReadB[((aIndex + 4944U)) & W_KEY1], 11U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 282U)) & S_BLOCK1], 13U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 5006U)) & S_BLOCK1], 24U));
            aCross ^= (RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 1120U)) & S_BLOCK1], 57U) ^ RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 4593U)) & S_BLOCK1], 43U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCarry, 23U) + RotL64(aPrevious, 11U)) + (RotL64(aCross, 41U) ^ RotL64(aIngress, 60U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = (aWandererB + RotL64(aPrevious, 53U)) + 0x6EBDD3CD9ECAF3D6ULL;
            aOrbiterI = (((aWandererC + RotL64(aScatter, 5U)) + RotL64(aCarry, 5U)) + 0x023B76E489E89F69ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 240U)) & S_SALT1];
            aOrbiterJ = ((aWandererA + RotL64(aIngress, 47U)) + 0x4472B3D422664DB9ULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 224U)) & S_SALT1];
            aOrbiterC = (aWandererI + RotL64(aCross, 19U)) + 0x3EDE429D1D01F1C4ULL;
            aOrbiterH = ((aWandererG + RotL64(aPrevious, 30U)) + RotL64(aCarry, 43U)) + 0xF9C50871ECF572F6ULL;
            aOrbiterD = (aWandererF + RotL64(aIngress, 11U)) + 0x87788677A70BE111ULL;
            aOrbiterG = ((aWandererK + RotL64(aCross, 41U)) + RotL64(aCarry, 23U)) + 0x05DD39859EB79A6AULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x576DA54DB48A5B18ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x6288FB360358E587ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x68E139B9BCE23D59ULL), 3U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0xBD0954B853B43C25ULL) + aKeyRotateAOrbiterUpdateSaltC[(((255U - aIndex) + 13U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0xD99D378EDE5943C6ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x9D3D4DBF37116F17ULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x8BB22A44D57371C0ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0x4A5F443A109E0E45ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((255U - aIndex) + 78U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x98554162DAE1535DULL), 43U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x2E48C49BF1AAB5D5ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x705C51FAD1766FD5ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x32EE2742D9A6CCCFULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0xD9106CDCE245DE6FULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xFC7320EF8F18B695ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x9FBBC76F3DF352B3ULL), 19U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0x8EA4A5F509B58881ULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 197U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x4C0BE55CC256E897ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x3093F35669F16E87ULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x6D2821A6CEF5AB4BULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x6297AF8CF93374E0ULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((255U - aIndex) + 97U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x6B9E33070895B1E7ULL), 27U);
            //
            aIngress = RotL64(aOrbiterD, 14U) ^ aOrbiterJ;
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterC, 3U));
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterG, 57U));
            aIngress = aIngress + RotL64(aOrbiterH, 51U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ (((RotL64(aCross, 35U) + RotL64(aOrbiterI, 4U)) + aOrbiterG) + aKeyRotateAWandererUpdateSaltA[((aIndex + 219U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aIngress, 19U) + RotL64(aOrbiterC, 11U)) + aOrbiterJ);
            aWandererK = aWandererK ^ ((RotL64(aScatter, 12U) + aOrbiterK) + RotL64(aOrbiterJ, 21U));
            aWandererG = aWandererG + (((RotL64(aPrevious, 47U) + aOrbiterJ) + RotL64(aOrbiterG, 39U)) + RotL64(aCarry, 43U));
            aWandererF = aWandererF ^ ((RotL64(aIngress, 27U) + aOrbiterG) + RotL64(aOrbiterK, 47U));
            aWandererC = aWandererC + (((RotL64(aCross, 41U) + RotL64(aOrbiterD, 53U)) + aOrbiterH) + RotL64(aCarry, 5U));
            aWandererA = aWandererA ^ (((RotL64(aScatter, 3U) + RotL64(aOrbiterD, 27U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltD[((aIndex + 18U)) & S_SALT1]);
            //
