            //
            aIngress = (RotL64(aFuseLaneA[((aIndex + 8990U)) & S_BLOCK1], 53U) ^ RotL64(aWindLaneC[((aIndex + 11264U)) & S_BLOCK1], 39U));
            aIngress ^= (RotL64(aSoilLaneC[((aIndex + 8511U)) & S_BLOCK1], 26U) ^ RotL64(aMagmaLaneC[((S_BLOCK1 - aIndex + 12276U)) & S_BLOCK1], 13U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 15700U)) & S_BLOCK1], 21U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 16134U)) & S_BLOCK1], 53U));
            aCross ^= (RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 14080U)) & S_BLOCK1], 12U) ^ RotL64(aPoisonLaneD[((aIndex + 15367U)) & S_BLOCK1], 29U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 57U) + RotL64(aCarry, 29U)) ^ (RotL64(aIngress, 42U) ^ RotL64(aCross, 5U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = ((aWandererI + RotL64(aCross, 51U)) + RotL64(aCarry, 39U)) + 0xEE91263FB9324DA3ULL;
            aOrbiterK = ((aWandererJ + RotL64(aIngress, 5U)) + RotL64(aCarry, 51U)) + 0x7F46A7A2EA9C9839ULL;
            aOrbiterD = ((aWandererK + RotL64(aPrevious, 43U)) + 0x9D5DBE7490E87420ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 87U)) & S_SALT1];
            aOrbiterC = ((aWandererC + RotL64(aScatter, 23U)) + 0x8E761597E7E4AFEDULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 16U)) & S_SALT1];
            aOrbiterH = (aWandererE + RotL64(aIngress, 13U)) + 0x56DF192E18C221CFULL;
            aOrbiterF = (aWandererH + RotL64(aPrevious, 29U)) + 0xB51A4DAA0730C57DULL;
            aOrbiterB = ((aWandererG + RotL64(aScatter, 60U)) + RotL64(aCarry, 21U)) + 0x9AB461F295F44732ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x69978560DCEA35CCULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterA) ^ 0x2CD383FB22FE31F5ULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 158U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x31067BF10829245FULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x4F450D6FE9F3215CULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x12A572128E5B3C14ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8FD08A3BD8711F21ULL), 13U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterC) + 0x3882335EB4CE834BULL) + aKeyRotateAOrbiterUpdateSaltB[(((255U - aIndex) + 97U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0x2AA127B148B538FEULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((255U - aIndex) + 47U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xC83A7A38A99D9C43ULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xEE44A06186BD32E3ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x28FCBB2C973C3361ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x5556B17A2325A623ULL), 43U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x2D957CAD9E123664ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x879E9A0853E81327ULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 184U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x18926957DBBA4D35ULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x3BE862FEEF356E5DULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x34B8C592141A1536ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC162624D4A3C7515ULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0xF0698DD6E466A078ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x9F3C5A1FD2303E2CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x20D54E07DAA140BFULL), 5U);
            //
            aIngress = RotL64(aOrbiterA, 41U) ^ aOrbiterD;
            aIngress = aIngress + (RotL64(aOrbiterF, 57U) ^ aOrbiterH);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterB, 10U));
            aIngress = aIngress + RotL64(aOrbiterK, 23U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererE = aWandererE ^ ((RotL64(aIngress, 13U) + RotL64(aOrbiterF, 58U)) + aOrbiterA);
            aWandererJ = aWandererJ + (((RotL64(aScatter, 29U) + aOrbiterD) + RotL64(aOrbiterH, 35U)) + RotL64(aCarry, 53U));
            aWandererG = aWandererG ^ ((RotL64(aCross, 51U) + aOrbiterC) + RotL64(aOrbiterK, 43U));
            aWandererH = aWandererH + (((RotL64(aPrevious, 57U) + aOrbiterD) + RotL64(aOrbiterA, 51U)) + aKeyRotateAWandererUpdateSaltB[(((255U - aIndex) + 233U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aScatter, 3U) + RotL64(aOrbiterB, 29U)) + aOrbiterK);
            aWandererI = aWandererI + ((((RotL64(aIngress, 21U) + aOrbiterF) + RotL64(aOrbiterC, 11U)) + RotL64(aCarry, 35U)) + aKeyRotateAWandererUpdateSaltE[(((255U - aIndex) + 149U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aCross, 42U) + aOrbiterA) + RotL64(aOrbiterK, 5U));
