            aOrbiterK = (((aWandererG + RotL64(aCross, 53U)) + RotL64(aCarry, 43U)) + 0x55DB41DD58BE9C36ULL) + aKeyRotateAOrbiterAssignSaltC[(((255U - aIndex) + 251U)) & S_SALT1];
