            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0xE70387B67A2CDD89ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xF0989B17AD5AD9F4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xCC95A65EA295091FULL), 29U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0xD0FB8692A33F278EULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 157U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0x9F5E02640CEEFD74ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xDC232A090AA289A5ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x861A6967C381197BULL;
