            aOrbiterK = ((aWandererE + RotL64(aScatter, 51U)) + RotL64(aCarry, 43U)) + 0x5FD7ABB543C6718FULL;
            aOrbiterJ = (aWandererI + RotL64(aPrevious, 11U)) + 0xD7A8D5829C2F89D6ULL;
            aOrbiterD = ((aWandererA + RotL64(aIngress, 43U)) + 0x8841B019F4CBA2E2ULL) + aKeyRotateBOrbiterAssignSaltC[(((255U - aIndex) + 71U)) & S_SALT1];
            aOrbiterG = ((aWandererD + RotL64(aScatter, 3U)) + 0xDB9918D39B1D568CULL) + aKeyRotateBOrbiterAssignSaltF[((aIndex + 109U)) & S_SALT1];
            aOrbiterE = (aWandererB + RotL64(aPrevious, 57U)) + 0xB19EE3E5538225A4ULL;
